mapper.select:
select w.id, w.work_order_no, w.fault_record_id, w.equipment_id,
       e.code as equipment_code, e.name as equipment_name,
       w.priority, w.status, w.maintainer_id,
       u.display_name as maintainer_name, w.due_at, w.created_at
from work_order w
join equipment e on e.id = w.equipment_id
left join sys_user u on u.id = w.maintainer_id

    and w.work_order_no like concat('%', #{workOrderNo}, '%')
    and w.equipment_id = #{equipmentId}
    and w.maintainer_id = #{maintainerId}
    and w.priority = #{priority}
    and w.status = #{status}
    and w.created_at >= #{createdFrom}
    and w.created_at < date_add(#{createdTo}, interval 1 day)

order by w.created_at desc, w.id desc

select f.url from biz_attachment b join file_object f on f.id = b.file_id
where b.biz_type = 'REPAIR' and b.biz_id = #{workOrderId}
order by b.sort_no, b.id

mapper.update:
update work_order
set maintainer_id = #{maintainerId},
due_at = #{dueAt},
assigned_at = #{assignedAt},
status = 'PENDING_ACCEPTANCE',
version = version + 1
where id = #{workOrderId}
and status = #{currentStatus}
and version = #{version}

update work_order
set status = 'PROCESSING', accepted_at = #{acceptedAt}, version = version + 1
where id = #{workOrderId}
  and maintainer_id = #{maintainerId}
  and status = 'PENDING_ACCEPTANCE'
  and version = #{version}

update work_order
set status = 'PENDING_VERIFICATION',
    solution = #{solution},
    result_description = #{resultDescription},
    submitted_at = #{submittedAt},
    version = version + 1
where id = #{workOrderId}
  and maintainer_id = #{maintainerId}
  and status = 'PROCESSING'
  and version = #{version}

update work_order
set status = 'PROCESSING', version = version + 1
where id = #{workOrderId}
  and maintainer_id = #{maintainerId}
  and status = 'REJECTED'
  and version = #{version}
